const T_MIX = [["Employer", "Base", "Variable", "Benefits", "Total"], ["A", "$65,000", "$5,000", "$20,000", "$90,000"], ["B", "$55,000", "$20,000", "$15,000", "$90,000"]];
const T_GRID10 = [["Rating", "CR 80–90%", "CR 91–110%", "CR 111–120%"], ["Exceeds", "7%", "5%", "3%"], ["Meets", "4%", "3%", "2%"], ["Below", "2%", "0%", "0%"]];
const T_GRID11 = [["Rating", "CR < 0.90", "CR 0.90–1.10", "CR > 1.10"], ["Exceeds", "6%", "5%", "4%"], ["Meets", "4%", "3%", "2%"], ["Below", "0%", "0%", "0%"]];
const T_SURVEY = [["Short-term plan", "% of orgs"], ["Annual incentive plan", "89%"], ["Spot cash awards", "50%"], ["Discretionary bonus", "34%"], ["Retention bonus", "32%"], ["Project bonus", "16%"], ["Profit sharing", "14%"], ["Team incentives", "12%"], ["Gainsharing", "4%"]];
