/* ---------- question bank ----------
   M(chapter, difficulty 1-3, question, [correct, wrong...], explanation, table?)
   T(chapter, difficulty, statement, true/false, explanation)            */
const BANK = [];
function M(c, d, q, a, e, tbl) { BANK.push({ id: BANK.length, kind: "mc", c, d, q, a, e, tbl }); }
function T(c, d, q, tf, e) { BANK.push({ id: BANK.length, kind: "tf", c, d, q, tf, e }); }

/* Chapter 7 */
M(7,1,"External competitiveness refers to:",["Pay relationships across organizations — how our pay compares with competitors","Pay relationships among jobs inside one organization","The share of pay that is variable","Legal compliance of pay practices"],"External = across organizations. Internal alignment is about jobs within one organization.");
M(7,1,"Pay level is best defined as:",["The average pay an employer offers relative to competing employers","The combination of base pay, incentives, and benefits","The gap between the highest- and lowest-paid job","The legal minimum wage in the market"],"Pay level = average amount paid relative to competitors. The combination of forms is pay mix.");
M(7,1,"Pay mix is:",["The combination of base pay, incentives, benefits, and other rewards","The average amount paid relative to competitors","The number of pay grades in a structure","Salary divided by range midpoint"],"Pay mix = the forms of pay. Two firms with the same total can have very different mixes.");
M(7,1,"The two objectives of external competitiveness decisions are to:",["Control labor costs and attract & retain employees","Ensure internal equity and legal compliance","Maximize benefits and minimize turnover","Set merit budgets and appraise performance"],"Slide: Control labor costs (pay level × number of employees) and attract & retain employees.");
M(7,2,"Using the table, which statement is TRUE?",["Total pay is equal, but B's mix may attract more risk-tolerant, performance-driven people","A has a higher pay level than B","B lags the market and A leads it","Because totals match, both will attract the same employees"],"Same $90,000 total, different mix. B puts more pay at risk ($20k variable), which sorts in performance-driven people.",T_MIX);
M(7,2,"Marginal REVENUE of labor is:",["The revenue generated by the extra output of one more employee","The extra output produced by one more employee","Total revenue divided by headcount","The wage needed to attract one more employee"],"Marginal product = extra output. Marginal revenue = the revenue from that extra output.");
M(7,2,"Marginal PRODUCT of labor is:",["The additional output from one more employee","The revenue from one more employee's output","The average output per employee","The cost of one more employee"],"Marginal product is output; marginal revenue converts it to dollars.");
M(7,2,"An employer should keep adding employees as long as:",["Marginal revenue of the next hire is greater than that hire's cost","Marginal product is positive","Average pay is below the market","Turnover is above the industry average"],"Hire when MR of labor > employment cost.");
M(7,2,"Efficiency wage theory says paying ABOVE market can:",["Attract stronger applicants, reduce turnover, and increase effort","Always lower total labor costs","Guarantee higher profit regardless of productivity","Remove the need for pay surveys"],"Efficiency wages: higher pay → better applicants, less turnover, more effort (a demand-side effect).");
M(7,2,"Under sorting & signaling, a pay package heavy on incentives mainly:",["Signals the employer values performance and influences who joins or stays","Shows the product market is uncompetitive","Pushes wages below applicants' reservation wage","Means the firm uses broadbanding"],"The package sends a signal; applicants self-select (sort) based on it.");
M(7,1,"A reservation wage is:",["The lowest wage an applicant will accept","The wage held back for top performers","The midpoint of a pay range","The legally required minimum wage"],"Supply side: each applicant's personal minimum acceptable wage.");
M(7,2,"Human capital theory predicts that:",["Education, training, and experience raise productivity and therefore earnings","Pay depends only on product demand","Risky jobs must pay more","Higher pay always increases effort"],"Supply side: investments in human capital raise productivity and earnings.");
M(7,2,"Compensating differentials explain why:",["Unpleasant or risky jobs must pay more to attract workers","High performers receive bonuses","Large firms pay more than small firms","Product competitors pay similar wages"],"Workers need extra pay to accept unpleasant or risky job attributes.");
M(7,3,"Intense competition in a firm's PRODUCT market tends to:",["Limit its ability to pass higher labor costs on to customers","Let it lead the labor market freely","Raise applicants' reservation wages","Make pay surveys unnecessary"],"Product market sets what the firm can recover. Strong price competition caps labor costs.");
M(7,2,"Which is an ORGANIZATION factor that shapes pay level?",["Industry, size, technology, and business strategy","Customer demand for the product","Applicants' reservation wages","The marginal product of labor"],"Organization factors: strategy, industry, size, technology, employee preferences.");
M(7,3,"A grocery chain is hiring software engineers. Its relevant LABOR market is:",["Employers that compete for software engineers, even in other industries","Other grocery chains only","Every employer in its city, for every job","Firms that sell to the same customers"],"Labor competitors can differ from product competitors. Define by occupation, geography, and competitors for the same skills.");
M(7,2,"The three things to consider when defining the relevant labor market are:",["Occupation, geography, and competitors","Pay level, pay mix, and benefits","Expectancy, instrumentality, and valence","Base, total cash, and total compensation"],"Slide 7: occupation, geography, competitors (product vs labor).");
M(7,1,"Which pay-level policy sets pay ABOVE the market?",["Lead","Match","Lag","Broadband"],"Lead = above, match = near, lag = below market.");
M(7,2,"The main risk of a LAG policy is:",["Hiring and retention may suffer","Higher costs that must earn a return","No advantage at all on pay","Legal noncompliance"],"Lag lowers current cash cost but can hurt attraction and retention.");
M(7,2,"The main risk of a LEAD policy is:",["Higher costs that must be recovered through productivity, quality, or another return","Difficulty attracting applicants","Little advantage on pay alone","Lower applicant quality"],"Lead supports attraction and retention, but higher costs require a return.");
M(7,2,"The main risk of a MATCH policy is:",["Little competitive advantage on pay alone","Very high labor costs","Severe hiring problems","Illegal pay discrimination"],"Match gives comparable costs and hiring access but no pay edge.");
M(7,3,"A firm matches the market on base pay but leads on incentives. This shows that:",["Pay-level policy can differ by form of pay (and by job or unit)","The firm is lagging overall","It violates external competitiveness","Pay mix does not matter"],"Slide 8: a firm might lead on incentives while matching base pay.");
M(7,2,"A firm emphasizes flexible schedules, generous leave, and wellness benefits. Its pay mix stresses:",["Work–life balance","Performance driven","Security","Shared choice"],"Pay mix options: performance driven, work-life balance, security, shared choice.");
M(7,2,"Employees pick among reward options within limits. This pay-mix approach is:",["Shared choice","Security","Performance driven","Lag policy"],"Shared choice = employees select within limits.");
M(7,3,"Stable base pay and predictable benefits with little variable pay describes which pay mix?",["Security","Performance driven","Shared choice","Lead"],"Security = stable pay and predictable benefits.");
T(7,1,"Two employers can offer the same total compensation and still attract different employees because of pay mix.",true,"Yes — the $90,000 A vs B example.");
T(7,2,"Product-market competitors and labor-market competitors are always the same organizations.",false,"They can differ — e.g., tech firms compete with a grocery chain for software engineers.");
T(7,1,"A lag policy lowers current cash costs but may hurt hiring and retention.",true,"That is the lag trade-off.");
T(7,2,"Paying above market always guarantees higher productivity.",false,"Higher pay needs a return; it is not guaranteed.");
T(7,2,"A company can use different pay-level policies for different occupations or forms of pay.",true,"Slide 8: policies can vary by occupation, unit, or form of pay.");
T(7,2,"Efficiency wage theory is a supply-side explanation of pay.",false,"Efficiency wages and sorting/signaling are DEMAND-side. Reservation wage and human capital are supply-side.");

/* Chapter 8 */
M(8,1,"Which is NOT a main purpose of a pay survey?",["Rating individual employees' performance","Setting the pay level","Evaluating the pay mix","Building or validating the pay structure"],"Survey purposes: pay level, pay mix, structure, specific problems, competitors' labor costs.");
M(8,1,"Benchmark jobs are:",["Jobs with recognizable, comparable content that anchor market comparisons","The highest-paid jobs in the company","Jobs unique to one employer","Jobs filled by the newest employees"],"Benchmarks are stable, well-known jobs you can match across firms.");
M(8,2,"When matching your jobs to survey jobs you should:",["Compare actual job content, not just titles","Match by job title only","Only use jobs that exist in every industry","Pick whichever survey job pays the most"],"Titles alone are not enough — compare content and use judgment.");
M(8,2,"Total CASH compensation includes:",["Base pay plus bonuses and other cash incentives","Base pay only","Base pay, incentives, and benefits","Benefits only"],"Base → total cash (adds bonuses) → total compensation (adds benefits).");
M(8,2,"Which pay measure is broadest but makes comparisons most complex?",["Total compensation","Base pay","Total cash","Merit increase"],"Total compensation adds benefits and other rewards.");
M(8,2,"Base pay data is best for:",["Comparing the market value of similar work","Seeing the effect of bonuses","Comparing benefit costs","Measuring individual performance"],"Slide 3: base pay is best for comparing market value of similar work.");
M(8,2,"As a job becomes more specialized or senior, its relevant geographic market usually:",["Expands (regional, national, or global)","Shrinks to the local area","Stays exactly the same","Stops mattering"],"Senior/specialized talent is recruited from farther away.");
M(8,2,"A 'fuzzy' market describes:",["New or hybrid jobs that do not map cleanly onto one occupation or industry","A market with unreliable survey vendors","A market where every employer pays the same","A market where pay is set by law"],"Fuzzy markets: hybrid skills that don't fit one comparison group.");
M(8,3,"A MARKET PAY LINE is:",["A regression line linking internal job value (e.g., JE points) to market pay for benchmark jobs","The line after adjusting the market for a lead/lag policy","A line connecting range minimums","A line connecting the highest-paid employees"],"Market pay line = regression of market rates on job evaluation results. The policy line adjusts it.");
M(8,3,"Using the regression, what is the predicted market pay for a 400-point job?",["$60,000","$40,000","$20,400","$80,000"],"$20,000 + $100 × 400 = $60,000.",T_REG);
M(8,3,"Using the regression, the firm LEADS the market by 10%. What is the pay policy line value at 400 points?",["$66,000","$60,000","$70,000","$54,000"],"Market = $60,000. Lead 10% → $60,000 × 1.10 = $66,000.",T_REG);
M(8,3,"Using the regression, the firm LAGS the market by 5%. Pay policy for a 300-point job is:",["$47,500","$50,000","$52,500","$45,000"],"Market = $20,000 + $30,000 = $50,000. Lag 5% → $47,500.",T_REG);
M(8,3,"What does the R² of 0.92 in this regression tell you?",["Job evaluation points explain most of the variation in market pay","92% of jobs are paid above market","The firm pays 92% of the market","Only 8% of jobs are benchmarks"],"R² = share of variance in market pay explained by JE points. 0.92 = a strong fit.",T_REG);
M(8,3,"The PAY POLICY LINE differs from the market pay line because it:",["Adjusts the market line to reflect the firm's lead, match, or lag policy","Uses only non-benchmark jobs","Shows the minimum of each pay range","Ignores market data"],"Policy line = market line + the firm's competitive policy.");
M(8,2,"In a pay survey, the 50th percentile is:",["The median — half of the reported rates fall below it","The average of the highest and lowest rate","The most common rate","The top half's average"],"50th percentile = median. A 'match' policy often targets it.");
M(8,1,"A pay GRADE groups:",["Different jobs treated as substantially equal for pay purposes","Employees by performance rating","Employees by seniority","Only identical jobs"],"Jobs in a grade share the same pay range.");
M(8,1,"A pay RANGE sets:",["A minimum, midpoint, and maximum for jobs in a grade","One flat rate for each job","The market's 50th percentile","The size of each bonus"],"Ranges allow pay differences for experience and performance.");
M(8,2,"Range spread is calculated as:",["(Maximum ÷ Minimum) − 1","Maximum − Minimum","Maximum ÷ Midpoint","(Maximum + Minimum) ÷ 2"],"Slide formula: (Max ÷ Min) − 1. (Max + Min) ÷ 2 is a midpoint.");
M(8,3,"Using the Grade 2 range, the range spread is about:",["50%","22%","33%","150%"],"$65,875 ÷ $43,917 = 1.50 → 1.50 − 1 = 50%.",T_RANGE);
M(8,2,"Pay ranges allow different pay within one grade mainly for:",["Experience and performance","Job title","Department name","Office location only"],"Slide: ranges recognize differences in experience and performance.");
M(8,2,"Compared with traditional grades, BROADBANDING uses:",["Fewer, wider bands that support lateral and cross-functional moves","More grades with narrower ranges","Tighter midpoint controls","No managerial discretion"],"Broadbanding = fewer, wider bands; flexibility within guidelines.");
M(8,3,"The main risk of broadbanding is:",["Inconsistency and favoritism from greater managerial discretion","Rigidity and limited flexibility","Too few lateral moves","Too many midpoint controls"],"Broad bands → discretion → risk of inconsistency/favoritism. Rigidity is the traditional grades' risk.");
M(8,3,"The main risk of traditional grades and ranges is:",["Rigidity and limited flexibility","Inconsistency and favoritism","Too much managerial discretion","No promotion steps"],"Traditional: structured progression and controls, but rigid.");
M(8,2,"Traditional grades and ranges fit best when the organization needs:",["Structured progression and built-in cost controls","Maximum lateral movement","Wide managerial discretion","No pay structure at all"],"'Flexibility within controls.'");
M(8,2,"Using multiple survey sources helps you:",["Cross-check and validate the market picture","Avoid matching job content","Skip the relevant-market step","Guarantee a lead policy"],"Slide 3: use multiple sources to cross-check.");
M(8,3,"A targeted survey to explain unusual turnover in one job family is an example of:",["Investigating a specific problem","Setting the overall pay level","Rating employee performance","Broadbanding"],"Surveys can investigate specific problems like turnover in particular jobs.");
T(8,1,"Job titles alone are enough to match jobs in a pay survey.",false,"Compare job content, not titles.");
T(8,2,"Range spread = (Maximum ÷ Minimum) − 1.",true,"That is the slide formula.");
T(8,2,"Broadbanding usually uses more grades with narrower ranges than a traditional structure.",false,"Broadbanding = fewer, WIDER bands.");
T(8,2,"A pay survey is the pay decision itself.",false,"'The survey is a means to a decision — not the decision itself.'");
T(8,2,"For a lead policy, the pay policy line sits above the market pay line.",true,"Lead = policy line above the market line.");
T(8,1,"Benchmark jobs should represent enough of the job hierarchy to help price the broader structure.",true,"Benchmarks should 'cover the structure.'");

/* Chapter 9 */
M(9,1,"Designing pay for performance should start with:",["Strategy, then the behaviors needed, then the rewards","The rewards, then the strategy","The market survey, then the strategy","The appraisal form"],"Slide: Strategy → Behaviors → Rewards.");
M(9,1,"The three parts of expectancy theory are:",["Expectancy, instrumentality, and valence","Equity, reinforcement, and goals","Hygiene factors, motivators, and needs","Attraction, retention, and turnover"],"Motivation = E × I × V.");
M(9,2,"'Will my PERFORMANCE actually lead to a reward?' is:",["Instrumentality","Expectancy","Valence","Equity"],"Instrumentality = performance → reward link.");
M(9,2,"'Will my EFFORT improve my performance?' is:",["Expectancy","Instrumentality","Valence","Reinforcement"],"Expectancy = effort → performance link.");
M(9,2,"An employee doesn't care about the gift card offered for hitting a goal. Which link fails?",["Valence","Expectancy","Instrumentality","Line of sight"],"Valence = how much the employee values the reward.");
M(9,3,"Because motivation = E × I × V:",["If any one link is near zero, motivation collapses","The three links simply add together","Valence is the only link that matters","High instrumentality makes up for zero expectancy"],"Multiplicative: a zero anywhere makes the product zero.");
M(9,2,"Herzberg's two-factor theory suggests that pay:",["Can cause dissatisfaction if inadequate, but more pay alone does not necessarily motivate","Is the strongest motivator in every case","Has no effect on satisfaction","Only satisfies self-actualization needs"],"Pay is a hygiene factor; achievement, growth, and the work itself motivate.");
M(9,2,"In Maslow's hierarchy, base pay mainly helps:",["Meet basic needs","Reach self-actualization directly","Create esteem automatically","Replace the need for recognition"],"Once basic needs are met, rewards tied to higher needs may motivate.");
M(9,1,"Maslow and Herzberg are examples of:",["Content theories (what employees value)","Process theories (how rewards motivate)","Agency theories","Labor market theories"],"Content = what people need/value. Process = how motivation works (expectancy, equity, etc.).");
M(9,2,"Equity theory says employees:",["Compare their contributions and rewards with others'","Work hardest when rewards follow behavior closely","Need specific, challenging goals","Act as agents of the owners"],"Perceived unfairness changes behavior.");
M(9,2,"Reinforcement theory says rewards work best when:",["They closely follow the behavior being encouraged","They are paid once a year","They are the same for everyone","They are kept secret"],"Timing matters — reward soon after the behavior.");
M(9,2,"Goal-setting theory recommends:",["Specific, challenging goals with regular feedback","Vague goals so employees stay flexible","Easy goals everyone can hit","Goals without feedback"],"Specific + challenging + feedback directs effort.");
M(9,3,"Agency theory says incentives can:",["Align employees' (agents') interests with owners' (principals') objectives","Make employees compare pay with coworkers","Reduce the need for performance measures","Guarantee intrinsic motivation"],"Principal–agent alignment, e.g., executive stock pay.");
M(9,2,"SORTING effects of pay concern:",["Who joins, stays, and leaves the organization","How hard current employees work","The timing of rewards","The pay survey sample"],"Sorting = who works here.");
M(9,2,"INCENTIVE effects of pay concern:",["How current employees change effort or behavior","Who applies to the organization","Which firms are in the survey","The pay range spread"],"Incentives = how people work once here.");
M(9,3,"After a firm adds individual incentives, low performers quit and high performers apply. This is:",["A sorting effect","An incentive effect","A compensating differential","Central tendency"],"Workforce composition changed → sorting.");
M(9,3,"Which applicants are most likely to prefer jobs with a lot of variable pay?",["Risk-tolerant applicants","Risk-averse applicants","Applicants seeking security","Applicants with high reservation wages only"],"Slide 8: risk-tolerant employees may prefer more variable pay.");
M(9,2,"'Line of sight' means employees:",["Can see how their actions affect the measure and the reward","Sit close to their manager","Know coworkers' salaries","Can view the pay survey"],"Needed for incentive effects: meaningful measures, credible link, valued outcomes.");
M(9,3,"Which is an UNINTENDED consequence of a poorly designed incentive?",["Gaming the metric and focusing narrowly on what is measured","Clear goals","Better line of sight","Higher valence"],"Watch for gaming, narrow focus, risk shifting, and damaged cooperation.");
M(9,3,"PROCEDURAL justice in an incentive plan concerns:",["The fairness of how rewards are determined","The fairness of the amount received","The size of the merit budget","Whether the job is a benchmark"],"Distributive = amounts. Procedural = process.");
M(9,3,"Pay for performance is LIKELY LESS effective when:",["Performance is hard to measure and outside employees' control","Measures are clear and current","Employees value the rewards","Line of sight is strong"],"Weak measures and low control break the E and I links.");
M(9,3,"A company pays sales reps only on individual sales but hopes they will share leads. Kerr calls this:",["Rewarding A while hoping for B","Efficiency wages","Broadbanding","Calibration"],"Kerr: reward systems often pay for one behavior while hoping for another.");
M(9,2,"Not all turnover is harmful because:",["What matters is which employees enter and exit","Turnover never affects costs","Pay never affects turnover","High performers never leave"],"Slide 8: the key is who enters and exits.");
T(9,1,"According to Herzberg, more pay always produces more motivation.",false,"More pay does not always mean more motivation.");
T(9,1,"Expectancy theory says motivation depends on expectancy, instrumentality, and valence together.",true,"E × I × V.");
T(9,2,"Sorting effects change who works for the organization, not just how hard people work.",true,"Sorting = composition of the workforce.");
T(9,2,"All turnover caused by pay for performance is harmful.",false,"Losing low performers can help.");
T(9,1,"Reinforcement theory says rewards work best when they closely follow the behavior.",true,"Timing matters.");
T(9,2,"Distributive justice is about the fairness of the process used to decide rewards.",false,"That is procedural justice. Distributive = fairness of the amounts.");

/* Chapter 10 */
M(10,1,"A MERIT INCREASE is:",["An annual increase to base pay based on a performance evaluation","A one-time cash award that does not change base pay","A share of company profits","Stock granted to all employees"],"Merit increases build into base pay, usually within a grade.");
M(10,2,"A merit BONUS (lump sum) differs from a merit increase because it:",["Does not become part of base salary","Is always larger","Is based on seniority","Is paid only to executives"],"The choice is whether the reward becomes fixed pay.");
M(10,1,"Compa-ratio equals:",["Current salary ÷ range midpoint","Range maximum ÷ range minimum","Midpoint ÷ market rate","Raise ÷ salary"],"CR = salary ÷ midpoint.");
M(10,3,"Using the merit grid, an employee rated MEETS has a compa-ratio of 85%. What is the raise?",["4%","3%","2%","7%"],"85% falls in the 80–90% column; Meets → 4%.",T_GRID10);
M(10,3,"Using the merit grid: rated EXCEEDS, salary $55,000, midpoint $50,000. What is the raise in dollars?",["$2,750","$3,850","$1,650","$5,500"],"CR = 55,000 ÷ 50,000 = 110% → 91–110% column → 5% × $55,000 = $2,750.",T_GRID10);
M(10,3,"Why does the grid give LOWER raises to people with a high compa-ratio?",["They are already paid high in the range, so smaller raises control cost and keep pay near the range","They are always weaker performers","The law requires it","Their jobs are not benchmarks"],"Higher position in range → smaller % keeps pay in line and lets lower-paid strong performers catch up.",T_GRID10);
M(10,2,"A MERIT increase vs a PROMOTION:",["Merit is within-grade growth; promotion moves to a higher role or grade","They are the same thing","Promotion never changes pay","Merit always moves you up a grade"],"Promotions often come with a larger salary change.");
M(10,2,"A SPOT award is:",["A small, immediate award for a specific accomplishment","A permanent increase to base pay","A three-year stock grant","A share of plant-wide savings"],"Spot cash awards are used by ~50% of orgs in the survey.");
M(10,2,"A plan pays $2 for every unit assembled. This is a:",["Piece-rate plan (units per period, constant rate)","Standard-hour (time-based) plan","Gainsharing plan","Merit pay plan"],"Standard set as units produced; constant pay per unit.");
M(10,2,"A mechanic is paid for the standard 3 hours on a brake job even when finishing in 2. This is a:",["Time-based (standard hour) plan","Straight piece rate","Profit sharing plan","Spot award"],"Standard set as time allowed per unit.");
M(10,2,"Main risks of INDIVIDUAL incentive plans:",["Narrow focus, gaming, and conflict among coworkers","Free riding","Weak line of sight","Too much cooperation"],"Slide 5: returns are strong; risks are narrow focus, gaming, conflict.");
M(10,2,"The classic disadvantage of TEAM / group incentives is:",["Free riding and weak individual line of sight","Too much individual competition","Excess line of sight","No need for measurement"],"High performers may also feel underrewarded.");
M(10,2,"Group incentives make most sense when:",["The work truly requires interdependent, joint effort","Each employee works alone","Output is easy to count per person","Managers want less cooperation"],"Use group incentives when the work requires joint effort.");
M(10,2,"GAINSHARING rewards employees for:",["Measured improvements in productivity, quality, or controllable costs","Overall company profit","Stock price over three years","Seniority"],"Measure → Improve → Share.");
M(10,3,"Profit sharing vs gainsharing:",["Profit sharing rewards the financial outcome; gainsharing emphasizes controllable improvements","They are identical","Gainsharing is tied to stock price","Profit sharing has stronger line of sight"],"Slide 8 bottom line.");
M(10,2,"The main challenge of PROFIT sharing is:",["Most employees have little direct control over profits","It is never self-funded","It has the strongest line of sight","It ignores organizational success"],"Weak line of sight.");
M(10,2,"An advantage of profit sharing is that:",["Variable pay can be largely self-funded","Employees directly control profits","It removes all financial risk","It eliminates free riding"],"Pays out only when profits exist.");
M(10,3,"Key conditions for successful gainsharing:",["Credible measures, employee participation, and supportive management","Secret formulas and top-down control","Stock options for executives only","Forced ranking"],"Slide 7.");
M(10,2,"A major risk of an ESOP is:",["Employees' wealth becomes concentrated in their employer's stock","Employees have too much line of sight","It is a one-year plan","It is only for production workers"],"Concentrated financial risk.");
M(10,2,"Performance shares/units are usually tied to:",["Multi-year corporate objectives, often three years","Daily output","A single spot award","Seniority"],"Long-term = beyond the one-year horizon.");
M(10,2,"Vesting in broad-based stock plans mainly supports:",["Retention","Free riding","Short-term output","Central tendency"],"You must stay to vest.");
M(10,1,"Using the survey table, which plan is the most common short-term plan?",["Annual incentive plan","Spot cash awards","Profit sharing","Gainsharing"],"89% use an annual incentive plan.",T_SURVEY);
M(10,2,"Using the survey table, which plan is LEAST common?",["Gainsharing","Team incentives","Profit sharing","Project bonus"],"Gainsharing is at 4%.",T_SURVEY);
M(10,3,"Using the survey table, which conclusion is valid?",["Prevalence alone does not tell you payout size or motivational impact","Annual incentives are the most motivating plan","Gainsharing does not work","Spot awards pay more than retention bonuses"],"'Prevalence is not the same as payout size or motivational impact.'",T_SURVEY);
M(10,2,"The illustrative combination plan in the chapter mixes:",["75% individual + 25% group/company","50% individual + 50% stock","25% individual + 75% group","100% profit sharing"],"Weights should reflect the work, not an automatic formula.");
M(10,3,"What makes a pay-for-performance plan work? (pick the best set)",["Meaningful payout, challenging-but-achievable goals, accurate measures, clear communication","Many metrics, tiny payouts, secret rules","Only rewarding what is easy to measure","Maximum risk on every employee"],"Slide 11 'Make it work.'");
M(10,1,"Long-term incentives differ from short-term incentives mainly because they:",["Extend beyond a one-year horizon","Are paid weekly","Never involve stock","Are always individual"],"Long-term = sustained value creation.");
T(10,1,"A merit bonus builds into base salary.",false,"A merit bonus is a lump sum; it does NOT build into base.");
T(10,1,"Gainsharing was the least common short-term plan in the illustrative survey.",true,"4%.");
T(10,2,"ESOPs can expose employees to concentrated financial risk.",true,"Their savings ride on one company.");
T(10,2,"Employee ownership alone guarantees better performance.",false,"'Ownership alone does not guarantee better performance.'");
T(10,1,"Free riding is a disadvantage of group incentives.",true,"Some members coast on others' effort.");
T(10,2,"Profit sharing usually gives employees stronger line of sight than gainsharing.",false,"Gainsharing focuses on controllable improvements, so it has stronger line of sight.");

/* Chapter 11 */
M(11,1,"Performance appraisals feed into:",["Merit increases, promotions, and employee development","Only the pay survey","Only benefits enrollment","Only the range spread"],"Appraisals connect performance to pay and other decisions.");
M(11,1,"RANKING vs RATING formats:",["Ranking compares employees with each other; rating compares each employee with a standard","Both compare employees with each other","Ranking uses behavioral anchors; rating does not","Rating shows only order"],"Slide 3 bottom line.");
M(11,2,"Paired comparison is a type of:",["Ranking format","Rating format","Essay format","MBO"],"Ranking: straight, alternation, paired comparisons.");
M(11,2,"The main limitation of RANKING is that it:",["Shows order but not the size of differences between employees","Takes years to build anchors","Is hard to compare across employees","Ignores relative standing"],"#1 might be barely ahead or far ahead.");
M(11,2,"BARS (behaviorally anchored rating scales):",["Define each level with concrete examples of job behavior","Rank employees from best to worst","Use only written essays","Rate only financial results"],"Strength: clearer standards.");
M(11,2,"The main limitation of BARS is:",["The anchors take time to develop","It shows only order","Standards are vague adjectives","It cannot be used for teamwork"],"Slide 5.");
M(11,2,"A standard rating scale's biggest limitation:",["'Above average' can mean different things to different raters","It is hard to administer","It cannot compare employees","It requires agreed objectives"],"Adjective anchors are interpreted differently.");
M(11,2,"MBO (management by objectives) evaluates:",["Results against objectives the manager and employee agreed on in advance","Employees ranked against each other","Behavior using adjective scales","Written essays only"],"Agree on the result, deadline, and evidence of success.");
M(11,3,"A main limitation of MBO is that:",["Goals may leave out important work or reflect factors outside the employee's control","It has no observable result","Anchors take too long to build","It only shows rank order"],"Slide 6.");
M(11,2,"The essay format's main limitation:",["It is hard to compare employees","It shows only order","It requires a 5-point scale","It is too numerical"],"Slide 3.");
M(11,3,"The five criteria for judging an appraisal format are:",["Development, administration, research, cost, and validity","Halo, horn, recency, leniency, severity","Expectancy, instrumentality, valence, equity, goals","Occupation, geography, competitors, product, size"],"Slide 7.");
M(11,3,"A call-center job with clear, observable behaviors fits best with:",["BARS","Straight ranking","An essay","Profit sharing"],"Observable behaviors support behavioral anchors; clear agreed outcomes support MBO.");
M(11,3,"A project manager with clear, agreed outcomes and deadlines fits best with:",["MBO","Paired comparison","Essay","Central tendency"],"Clear, agreed outcomes support MBO.");
M(11,2,"The four balanced scorecard perspectives are:",["Financial, customer, internal processes, learning & growth","Lead, match, lag, mix","Base, cash, benefits, stock","Self, peer, boss, customer"],"Slide 2.");
M(11,2,"360-degree feedback collects ratings from:",["Supervisors, peers, subordinates, customers, and self","Only the supervisor","Only HR","Only customers"],"Multiple perspectives — but they still need shared standards.");
M(11,3,"INTERRATER RELIABILITY means:",["Different raters agree when rating the same performance","One rater is consistent over time only","Ratings match the market","Everyone gets the same rating"],"Should be assessed when using multiple raters.");
M(11,2,"Subordinates are best positioned to rate a manager's:",["Leadership, coaching, and support","Financial results","Customer service","Pay level"],"Slide 8 rater table.");
M(11,2,"Strong technical skills inflate ratings on teamwork and communication. This is:",["Halo error","Horn error","Recency error","Severity error"],"One strength raises all dimensions.");
M(11,2,"One missed deadline drags down ratings on every dimension. This is:",["Horn error","Halo error","Leniency error","Spillover error"],"One weakness lowers all dimensions.");
M(11,2,"A manager gives everyone 'exceeds expectations.' This is:",["Leniency error","Severity error","Central tendency","Halo error"],"Consistently too high.");
M(11,2,"Both strong and weak performers get 'meets expectations.' This is:",["Central tendency","Leniency","Recency","Clone error"],"Rater avoids the extremes.");
M(11,2,"A December success overshadows earlier missed goals. This is:",["Recency error","First impression error","Spillover error","Horn error"],"Recent performance outweighs the full period.");
M(11,3,"Last year's poor rating persists despite clear improvement. This is:",["Spillover error","Recency error","Severity error","Central tendency"],"Past judgments carry into the current period.");
M(11,3,"A familiar work style earns a higher rating than an equally effective one. This is:",["Clone / similarity error","Halo error","Leniency error","First impression error"],"Similarity to the rater.");
M(11,3,"A weak first week defines the employee's entire review. This is:",["First impression error","Recency error","Spillover error","Horn error"],"An early impression shapes later judgments.");
M(11,2,"A demanding manager gives strong performers low ratings. This is:",["Severity error","Leniency error","Central tendency","Clone error"],"Consistently too harsh.");
M(11,2,"RATER-ERROR training:",["Explains common biases so raters can avoid them","Clarifies which dimensions to evaluate","Uses examples to practice applying standards","Sets the merit budget"],"Three trainings: rater-error, performance-dimension, performance-standard.");
M(11,3,"PERFORMANCE-DIMENSION training:",["Clarifies what to evaluate","Explains common biases","Uses examples to practice applying standards","Compares ratings in a meeting"],"Dimension = WHAT to evaluate.");
M(11,3,"PERFORMANCE-STANDARD training:",["Uses examples to practice applying standards","Clarifies what to evaluate","Lists rating errors","Sets compa-ratios"],"Standard = HOW GOOD each level is, practiced with examples.");
M(11,2,"In a CALIBRATION meeting, managers:",["Compare draft ratings with evidence for similar work and revise when warranted","Rank all employees by seniority","Set the pay survey sample","Decide stock grants"],"Can also improve managers' motivation to rate accurately.");
M(11,2,"The three stages where rater judgment goes wrong are:",["Observation/attention, storage/recall, and evaluation","Strategy, behaviors, rewards","Measure, improve, share","Attraction, retention, turnover"],"Slide 9.");
M(11,3,"Using the merit grid: salary $44,000, midpoint $50,000, rated EXCEEDS. New salary?",["$46,640","$46,200","$45,760","$44,000"],"CR = 0.88 (< 0.90) → 6% → $44,000 × 1.06 = $46,640.",T_GRID11);
M(11,3,"Using the merit grid: salary $67,800, midpoint $60,000, rated MEETS. What raise %?",["2%","3%","4%","0%"],"CR = 1.13 (> 1.10) → Meets → 2%.",T_GRID11);
M(11,2,"Using the merit grid, an employee rated BELOW expectations with CR 0.85 gets:",["0%","2%","4%","6%"],"Below expectations earns 0% in every column of this grid.",T_GRID11);
M(11,2,"A GENERAL increase is:",["A common adjustment for everyone, sometimes tied to living costs","A raise based on appraised performance","A raise based on tenure","A one-time spot award"],"Merit = performance; general = common; seniority = tenure.");
M(11,2,"Which is a MANAGER responsibility in performance management?",["Give timely feedback and coach employees through problems","Seek feedback and receive it openly","Agree on deadlines with peers","Clarify one's own priorities"],"The others are employee responsibilities.");
M(11,2,"Results vs behaviors as performance measures:",["Results capture outcomes; behaviors capture how the work is done","They are the same","Behaviors capture only profit","Results capture only effort"],"Slide 2.");
T(11,1,"Ranking shows how much better one employee is than another.",false,"Ranking shows order but not the size of the differences.");
T(11,1,"Halo error is when one strength raises ratings across dimensions.",true,"Horn is the opposite.");
T(11,2,"Central tendency means ratings are consistently too high.",false,"Too high = leniency. Central tendency avoids the extremes.");
T(11,2,"Using 360-degree feedback removes the need to check interrater reliability.",false,"Multiple raters still need shared standards; reliability should be assessed.");
T(11,2,"Calibration meetings can improve managers' motivation to rate accurately.",true,"Slide 12.");
T(11,2,"In the illustrative merit grid, below-expectations performers get 0% regardless of compa-ratio.",true,"Bottom row is 0/0/0.");
T(11,1,"MBO evaluates outcomes against goals agreed on in advance.",true,"Management by objectives.");

/* ---------- scenario questions (professor-style applications) ---------- */
M(7,2,"A rural hospital pays nurses at the regional median but can't fill openings and keeps losing nurses to a city hospital. Which response best fits external competitiveness thinking?",["Lead the market for nurses, and track whether lower turnover and agency costs pay for it","Lag the market to save money for recruiting ads","Cut nurse benefits to fund executive raises","Ignore the market because product demand is stable"],"For a hard-to-fill job, a lead policy can help attraction and retention — but it needs a return.");
M(7,2,"A cash-poor startup pays 15% below market base pay but offers stock options and fully remote work. This is best described as:",["Lagging on base pay while competing through pay mix","Leading the market on pay level","A match policy","Efficiency wages"],"Firms can compete through the form of rewards, not only the amount.");
M(7,3,"A discount airline with thin margins and fierce price competition wants to lead the market for every job. The biggest concern is:",["Its product market limits its ability to pass higher labor costs on to customers","Applicants' reservation wages are too high","Its employees lack human capital","Leading never helps attraction"],"Product-market competition constrains what a firm can afford to pay.");
M(7,2,"Two offers have the same total pay. Offer A: high base, small bonus. Offer B: lower base, big bonus. A risk-averse new graduate will most likely choose:",["Offer A","Offer B","Neither — equal totals mean no preference","Whichever has more vacation only"],"Risk-averse people sort toward stable pay; risk-tolerant people toward variable pay.");
M(7,2,"A trucking company pays more for long-haul routes that keep drivers away from home for weeks. This is an example of:",["A compensating differential","Efficiency wages","A lag policy","Human capital"],"Unpleasant job attributes require extra pay.");
M(7,3,"A warehouse raises pay 12% above market. Turnover drops by half, and productivity gains more than cover the cost. This best supports:",["Efficiency wage theory","Compensating differentials","Reservation wage theory","A lag policy"],"Above-market pay → better applicants, lower turnover, more effort.");
M(7,1,"An applicant turns down a $48,000 offer because she won't work for less than $52,000. The $52,000 is her:",["Reservation wage","Market wage","Marginal revenue","Pay level"],"The lowest wage a person will accept.");
M(7,3,"A bank is hiring both entry-level tellers and a new CFO. How should the relevant labor markets differ?",["Tellers: local market; CFO: national market","Both should use the same local market","Tellers: national; CFO: local","Use product competitors only for both"],"Geographic scope widens as jobs become more senior or specialized.");
M(7,3,"A company with an older workforce shifts rewards toward retirement and health benefits and away from bonuses. It is changing its:",["Pay mix to fit employee preferences","Pay-level policy to lag","Relevant labor market","Marginal product"],"The same dollars can be delivered in different forms to match what employees value.");
M(7,2,"A tech firm and a hospital both recruit data analysts, even though they sell completely different products. For data analysts, they are:",["Labor market competitors","Product market competitors","Not competitors at all","Benchmark jobs"],"Labor competitors seek the same skills, even across industries.");
T(7,2,"A company that sells only in one city may still need a national labor market for some jobs.",true,"Senior and specialized roles often recruit nationally.");
T(7,2,"A firm that leads the market should still expect a return, such as lower turnover or higher productivity.",true,"Higher pay needs a return.");

M(8,2,"HR matches the company's 'Data Wizard' job to the survey's 'Data Analyst II' because about 85% of the duties are the same. This is:",["Good practice — match on job content, not titles","A mistake — titles must match exactly","A mistake — only executive jobs can be matched","Irrelevant — surveys don't use job content"],"Match on job content and use judgment.");
M(8,3,"Survey data were collected 12 months ago, and market pay is rising about 3% per year. Before using the data, HR should:",["Age (update) the data forward to the date the new pay takes effect","Discard the survey entirely","Use the data as-is","Lower the data by 3%"],"Survey data are a snapshot; trend them forward to when the pay will apply.");
M(8,2,"A small nonprofit uses one survey whose sample is mostly large tech companies. The main problem is:",["The comparison group doesn't represent its relevant market","The survey is too recent","Benchmark jobs can't be used","Total compensation is too broad"],"Good market data starts with the right comparison group.");
M(8,3,"An employee is paid ABOVE the maximum of her pay range. A common response is to:",["Freeze her base pay (red circle) and use lump sums until the range catches up","Raise the range minimum","Give her the largest merit increase","Move her to a lower grade immediately"],"Above-maximum rates are usually red-circled.");
M(8,3,"An employee is paid BELOW the minimum of his pay range. The usual fix is to:",["Raise his pay to at least the minimum (green circle)","Freeze his pay","Lower the range minimum","Reduce his merit increase"],"Below-minimum rates are usually brought up to the minimum.");
M(8,2,"A company wants marketing and product employees to move sideways between roles to build skills without needing a promotion. Which structure fits best?",["Broadbanding","Many narrow traditional grades","One flat rate for everyone","Seniority steps only"],"Broad bands support lateral and cross-functional moves.");
M(8,3,"A regression of market pay on job-evaluation points has an R² of 0.35. This suggests:",["The internal job hierarchy does not line up well with the market — check job matches and evaluations","The pay structure is perfectly aligned","The company leads the market by 35%","Only 35% of jobs are benchmarks"],"A low R² means JE points explain little of the variation in market pay.");
M(8,3,"One benchmark job (cybersecurity analyst) sits far ABOVE the market pay line. The most likely explanation is:",["A hot-skill market premium for that job","The job must be a data-entry error","The firm lags the market","The job has too few JE points by law"],"Some jobs command premiums because the supply of talent is tight.");
M(8,2,"Why might a firm compare TOTAL CASH rather than base pay for sales jobs?",["Sales jobs have large variable pay, so base pay alone understates market pay","Base pay can never be compared","Benefits are the main pay for sales jobs","Total cash excludes bonuses"],"Use total cash when variable pay is meaningful.");
T(8,2,"Two jobs with different titles can be valid survey matches if their job content is substantially the same.",true,"Content beats titles.");
T(8,3,"Survey data should usually be adjusted forward (aged) to the date the new pay rates take effect.",true,"The market keeps moving after the survey.");
T(8,2,"Broadbanding gives managers less discretion over pay than traditional grades.",false,"Broadbanding gives MORE discretion.");

M(9,2,"Sales reps say: 'No matter how hard I work, my territory is too small to hit quota.' Which link is weak?",["Expectancy (effort → performance)","Instrumentality (performance → reward)","Valence (value of the reward)","Equity"],"They don't believe effort can produce the performance.");
M(9,2,"Employees believe bonuses go to the manager's favorites regardless of results. Which link is weak?",["Instrumentality (performance → reward)","Expectancy (effort → performance)","Valence","Reinforcement"],"Performance doesn't credibly lead to the reward.");
M(9,2,"A company offers a $50 gift card to senior engineers earning $180,000 for finishing a major project early. Few seem motivated. The weak link is most likely:",["Valence","Expectancy","Instrumentality","Agency"],"The reward isn't valued.");
M(9,2,"A nurse learns that a coworker with the same experience earns $8,000 more, and she starts doing only the minimum. Which theory best explains this?",["Equity theory","Reinforcement theory","Goal-setting theory","Maslow's hierarchy"],"A perceived unfair comparison reduces effort.");
M(9,3,"A call center pays agents per call handled. Handle time drops, but complaints about rushed, unresolved calls rise. This is best described as:",["An unintended consequence — rewarding A (speed) while hoping for B (resolution)","A sorting effect","A compensating differential","Successful goal setting"],"Kerr's folly: incentives can encourage gaming and narrow focus.");
M(9,3,"A university rewards professors mainly for research publications but says teaching is its top priority. Kerr would call this:",["Rewarding A while hoping for B","Efficiency wages","Instrumentality","Broadbanding"],"A classic Kerr example.");
M(9,2,"A manager praises and rewards good work right when it happens instead of waiting for the annual review. This applies:",["Reinforcement theory","Equity theory","Agency theory","Herzberg's hygiene factors"],"Rewards work best when they closely follow the behavior.");
M(9,2,"A manager changes a goal from 'do your best on quality' to 'cut defects 15% by June 30, with weekly updates.' This applies:",["Goal-setting theory","Equity theory","Maslow's hierarchy","Compensating differentials"],"Specific, challenging goals plus feedback.");
M(9,3,"A board ties most of the CEO's pay to 3-year shareholder returns. Which theory most directly supports this?",["Agency theory","Equity theory","Reinforcement theory","Herzberg's two-factor theory"],"Align the agent's (CEO's) interests with the principals' (owners').");
M(9,3,"Pay for performance is MOST likely to work for which job?",["A sales rep with a clear individual territory and measurable sales","A research scientist on a 7-year team project","A receptionist whose output depends on others' schedules","A crew whose results depend mostly on the weather"],"Clear, controllable, measurable performance gives strong line of sight.");
M(9,3,"After adding large commissions, a firm finds that its best sellers stay and its weak sellers leave within a year. This is mainly:",["A sorting effect","An incentive effect","A compensating differential","Central tendency"],"The composition of the workforce changed.");
M(9,3,"After a piece rate is introduced, the SAME workers produce 20% more per hour. This is mainly:",["An incentive effect","A sorting effect","A signaling effect","A lag policy"],"The same people changing their effort = incentive effect.");
M(9,2,"Employees accept the size of their bonuses but are angry that nobody explained how bonuses were calculated. This is a problem of:",["Procedural justice","Distributive justice","Valence","Expectancy"],"Process fairness and communication.");
T(9,2,"If employees value the reward and believe effort leads to performance, but doubt performance will be rewarded, motivation can still be low.",true,"Weak instrumentality breaks E × I × V.");
T(9,3,"A pay plan that causes low performers to quit can improve the workforce even if nobody works harder.",true,"That is a sorting effect.");
T(9,2,"According to Kerr, organizations usually get the behavior they hope for, whatever they actually reward.",false,"They get what they reward.");

M(10,3,"A company wants to reward strong performance this year without permanently raising its fixed salary costs. The best choice is:",["A merit bonus (lump sum)","A merit increase to base pay","A promotion for everyone","A general cost-of-living increase"],"Lump sums don't build into base pay.");
M(10,2,"A software team's work is highly interdependent — nobody can finish without the others. Which incentive fits best?",["A team/group incentive","An individual piece rate","Individual sales commission","No incentive can work"],"Use group incentives when the work truly requires joint effort.");
M(10,2,"A plant forms employee committees to suggest ways to cut scrap and shares 50% of the measured savings with workers. This is:",["Gainsharing","Profit sharing","An ESOP","Merit pay"],"Measure, improve, share controllable gains.");
M(10,3,"Employees worked harder than ever, but a recession wiped out profits and the profit-sharing plan paid nothing. This shows:",["Profit sharing has weak line of sight — results depend on factors employees can't control","Profit sharing has the strongest line of sight","Gainsharing must also pay nothing","Employees should have had piece rates"],"Most employees have limited control over profits.");
M(10,3,"Employees hold most of their retirement savings in company stock through an ESOP, and then the company fails. This illustrates:",["The concentrated financial risk of employee ownership","Strong line of sight in ESOPs","The free-rider problem","A merit grid"],"ESOPs can concentrate employees' wealth in one company.");
M(10,2,"Stock options that vest over four years are mainly designed to:",["Retain employees","Reward last month's output","Stop free riding immediately","Replace base pay"],"Unvested value encourages people to stay.");
M(10,2,"An employee stays all weekend to fix a client crisis and receives a $500 award on Monday. This is a:",["Spot award","Merit increase","Profit-sharing payout","Performance share"],"A small, immediate award for a specific accomplishment.");
M(10,3,"A sales plan pays 80% on each rep's own sales and 20% on regional results. Why combine them?",["Keep individual line of sight while still rewarding cooperation and shared goals","To remove all measurement","Because the law requires 80/20","To make pay fully fixed"],"Combination plans balance individual and group outcomes.");
M(10,3,"A team incentive pays everyone equally, and top performers complain that some members coast. This is the:",["Free-rider problem","Line-of-sight advantage","Compensating differential","Halo error"],"A classic group-incentive disadvantage.");
M(10,3,"A piece-rate plant sees output soar, but quality drops and workers stop helping new hires. This shows a risk of individual incentives:",["Narrow focus and reduced cooperation","Free riding","Weak line of sight","Too much job security"],"Individual incentives can create conflict and narrow focus.");
T(10,2,"A merit increase given this year continues to cost the company in future years.",true,"It builds into base pay.");
T(10,3,"Gainsharing usually gives employees a clearer line of sight than company-wide profit sharing.",true,"Gains are tied to things the unit can influence.");
T(10,2,"Group incentives work best when each employee's output is completely independent of the others.",false,"Group incentives fit interdependent work.");

M(11,2,"A manager rates every employee 4 out of 5 to avoid uncomfortable conversations. This is:",["Leniency error","Severity error","Central tendency","Recency error"],"Ratings are consistently too high.");
M(11,3,"A manager keeps a short performance journal all year so reviews aren't based only on the last few weeks. This mainly guards against:",["Recency error","Halo error","Leniency error","Clone error"],"Documentation reduces reliance on recent memory (storage and recall).");
M(11,3,"A company requires managers to place the bottom 10% of employees in a 'needs improvement' category. This is a form of:",["Ranking (forced distribution)","BARS","MBO","Essay appraisal"],"A relative comparison among employees.");
M(11,2,"A manager can't see engineers' day-to-day collaboration. Who is best positioned to add input on it?",["Peers","Customers","Subordinates only","Nobody — skip that dimension"],"Peers see collaboration and day-to-day work.");
M(11,3,"Two managers rate employees with similar work and similar results as a 2 and a 4. The best fix is:",["A calibration meeting that compares evidence and standards","Ignoring the difference","Switching to essays only","Giving both a 3 without discussion"],"Calibration improves consistency (interrater reliability).");
M(11,3,"Raters watch videos of 'meets' and 'exceeds' performance and practice rating them against the standard. This is:",["Performance-standard training","Rater-error training","Performance-dimension training","Calibration"],"Practice applying standards with examples.");
M(11,3,"New managers aren't sure WHAT parts of the job they should evaluate. They need:",["Performance-dimension training","Rater-error training","Performance-standard training","A merit grid"],"Dimension training clarifies what to evaluate.");
M(11,2,"An MBO goal reads: 'Improve communication.' What is wrong with it?",["It has no measurable result, deadline, or evidence of success","It is too specific","MBO cannot include communication","Nothing — it is a strong MBO goal"],"Agree on the result, the deadline, and the evidence.");
M(11,3,"The merit budget is 3%. Top performers get 3.2% and average performers get 2.9%. The likely problem is:",["The differences are too small to show a meaningful pay–performance link","Top performers are overpaid","The budget is illegal","This guarantees strong motivation"],"Meaningful differences in raises help employees see the connection.");
M(11,2,"A sales job is evaluated on revenue, while a customer service job is evaluated on how reps handle callers. These use:",["Results (sales) vs behaviors (service)","Behaviors for both","Results for both","Rankings for both"],"Results capture outcomes; behaviors capture how the work is done.");
M(11,3,"A new employee stumbled in her first two weeks but has been excellent since. Her review still calls her 'struggling.' This is:",["First impression error","Recency error","Leniency error","Clone error"],"An early impression shapes later judgments.");
M(11,2,"An employee asks her manager for mid-year feedback and changes her work based on it. She is:",["Fulfilling an employee responsibility in performance management","Committing a rating error","Doing the manager's calibration job","Using MBO only"],"Employees should seek feedback and use it to improve.");
T(11,2,"Keeping documented examples throughout the year can reduce recency error.",true,"It helps storage and recall.");
T(11,3,"Calibration meetings are mainly used to set the company's pay-level policy.",false,"They align ratings across managers.");
T(11,2,"A forced distribution is a type of ranking format.",true,"It compares employees with each other.");

/* ---------- randomized calculation questions ----------
   New numbers on every run (from the run's seed, so a friend on the same code gets the same numbers). */
const GENS = [];
function G(c, d, make) { GENS.push({ c, d, make }); }
const rp = (r, a) => a[Math.floor(r() * a.length)];
function opts4(correct, cands, fb) { const out = [correct]; for (const x of cands.concat(fb || [])) if (!out.includes(x) && out.length < 4) out.push(x); return out; }
const fbM = v => [fmt$(v * 0.9), fmt$(v * 1.1), fmt$(v * 0.95), fmt$(v * 1.05)];

G(8, 2, r => { const a = rp(r, [15000, 18000, 20000, 25000]), b = rp(r, [80, 90, 100, 120]), p = rp(r, [250, 300, 350, 400, 450]), y = a + b * p;
  return { q: `A market pay line regression gives: Market pay = ${fmt$(a)} + $${b} × job-evaluation points. What is the predicted market pay for a ${p}-point job?`,
    a: opts4(fmt$(y), [fmt$(b * p), fmt$(a + b * (p + 50)), fmt$(y * 1.1)], fbM(y)), e: `${fmt$(a)} + $${b} × ${p} = ${fmt$(y)}.` }; });
G(8, 3, r => { const a = rp(r, [15000, 20000, 25000]), b = rp(r, [90, 100, 120]), p = rp(r, [300, 350, 400]), y = a + b * p, pc = rp(r, [5, 10, 15]), lead = r() < 0.5, m = 1 + (lead ? pc : -pc) / 100, v = y * m;
  return { q: `Market pay line: ${fmt$(a)} + $${b} × JE points. The firm's policy is to ${lead ? "LEAD" : "LAG"} the market by ${pc}%. What is the pay policy line value for a ${p}-point job?`,
    a: opts4(fmt$(v), [fmt$(y), fmt$(y * (2 - m)), fmt$(y + (lead ? 1 : -1) * pc * 1000)], fbM(v)), e: `Market = ${fmt$(y)}. ${lead ? "Lead" : "Lag"} ${pc}% → ${fmt$(y)} × ${m.toFixed(2)} = ${fmt$(v)}.` }; });
G(8, 3, r => { const m = rp(r, [50000, 60000, 70000, 80000]), s = rp(r, [40, 50, 60]), mn = m / (1 + s / 200), mx = mn * (1 + s / 100), f = (x, y) => `Min ${fmt$(x)} – Max ${fmt$(y)}`;
  return { q: `A pay grade has a ${fmt$(m)} midpoint and a ${s}% range spread. What are the range minimum and maximum?`,
    a: opts4(f(mn, mx), [f(m * (1 - s / 200), m * (1 + s / 200)), f(m * (1 - s / 100), m * (1 + s / 100)), f(mn, m * (1 + s / 100))], [f(mn * 0.95, mx * 0.95)]),
    e: `Min = midpoint ÷ (1 + spread ÷ 2) = ${fmt$(m)} ÷ ${(1 + s / 200).toFixed(2)} = ${fmt$(mn)}. Max = min × (1 + spread) = ${fmt$(mx)}.` }; });
G(8, 2, r => { const mn = rp(r, [40000, 45000, 50000, 60000]), s = rp(r, [30, 40, 50, 60]), mx = mn * (1 + s / 100);
  return { q: `A pay range runs from ${fmt$(mn)} (minimum) to ${fmt$(mx)} (maximum). What is the range spread?`,
    a: opts4(s + "%", [Math.round(s / 2) + "%", Math.round((mx - mn) / mx * 100) + "%", Math.round(mx / mn * 100) + "%"], ["10%", "75%"]), e: `(Max ÷ Min) − 1 = ${(mx / mn).toFixed(2)} − 1 = ${s}%.` }; });
G(8, 2, r => { const p50 = rp(r, [52000, 58000, 64000, 70000]), p25 = p50 - rp(r, [5000, 6000, 7000]), p75 = p50 + rp(r, [8000, 9000, 10000]), pol = rp(r, ["lead", "match", "lag"]), ans = { lead: p75, match: p50, lag: p25 }[pol];
  return { q: `Survey results for a benchmark job: 25th percentile ${fmt$(p25)}, 50th ${fmt$(p50)}, 75th ${fmt$(p75)}. The firm's policy is to ${pol.toUpperCase()} the market. Which rate is the best target?`,
    a: opts4(fmt$(ans), [fmt$(p25), fmt$(p50), fmt$(p75)], [fmt$(p50 * 1.2), fmt$(p25 * 0.9)]), e: "Lead ≈ above the median (e.g., 75th percentile); match ≈ the median (50th); lag ≈ below the median (e.g., 25th)." }; });
G(7, 2, r => { const mr = rp(r, [14, 18, 22, 26, 30]), w = rp(r, [16, 20, 24, 28]), yes = mr > w;
  return { q: `Hiring one more barista would add $${mr}/hour in revenue (marginal revenue of labor). The wage plus other costs is $${w}/hour. Should the café hire?`,
    a: yes ? [`Yes — marginal revenue ($${mr}) is greater than the cost ($${w})`, "No — marginal revenue is below the cost", "No — hire only at the market median", "No — marginal product must be zero first"]
           : [`No — marginal revenue ($${mr}) is less than the cost ($${w})`, "Yes — marginal revenue exceeds the cost", "Yes — any positive marginal product justifies hiring", "Yes — hiring always lowers average cost"],
    e: "Hire when the marginal revenue of labor is greater than the employment cost." }; });
G(7, 1, r => { const tot = rp(r, [80000, 90000, 100000]), ab = rp(r, [0.7, 0.75, 0.8]), bb = rp(r, [0.55, 0.6]), eq = r() < 0.5, totB = eq ? tot : tot + rp(r, [5000, -5000]);
  const A = [tot * ab, tot * 0.05, tot * (0.95 - ab)], Bo = [totB * bb, totB * 0.25, totB * (0.75 - bb)];
  const tbl = [["Offer", "Base", "Variable", "Benefits"], ["A", ...A.map(fmt$)], ["B", ...Bo.map(fmt$)]];
  const hi = totB > tot ? `Offer B has higher total compensation (${fmt$(totB)} vs ${fmt$(tot)})` : `Offer A has higher total compensation (${fmt$(tot)} vs ${fmt$(totB)})`;
  const lo = totB > tot ? `Offer A has higher total compensation` : `Offer B has higher total compensation`;
  return { q: "Using the table, which statement is TRUE?", tbl,
    a: eq ? ["Total compensation is equal; only the pay mix differs", "Offer A has the higher total compensation", "Offer B has the higher total compensation", "Offer B offers more pay security"]
          : [hi, "Total compensation is equal; only the pay mix differs", lo, "Offer A has more variable pay than Offer B"],
    e: `Add base + variable + benefits: A = ${fmt$(tot)}, B = ${fmt$(totB)}. Offer B puts more pay at risk (variable).` }; });
G(9, 3, r => { const names = shuffle(["Ana", "Ben", "Cara"], r), sets = shuffle([[rp(r, [0.8, 0.9]), 0.1, rp(r, [0.8, 0.9])], [0.7, rp(r, [0.8, 0.9]), 0.7], [0.5, 0.6, rp(r, [0.8, 0.9])]], r);
  const prod = sets.map(s => s[0] * s[1] * s[2]), best = prod.indexOf(Math.max(...prod));
  return { q: "Using the expectancy values in the table, which employee should be MOST motivated?",
    tbl: [["Employee", "Expectancy", "Instrumentality", "Valence"], ...names.map((n, i) => [n, ...sets[i].map(String)])],
    a: [names[best], ...names.filter((_, i) => i !== best), "All three are equally motivated"],
    e: `Motivation = E × I × V: ${names.map((n, i) => n + " " + prod[i].toFixed(3)).join(", ")}. One weak link (like I = 0.1) sinks the product.` }; });
G(10, 3, r => { const col = Math.floor(r() * 3), cr = rp(r, [[82, 85, 88], [95, 100, 105], [112, 115, 118]][col]), mid = rp(r, [50000, 60000, 70000]), sal = Math.round(mid * cr / 100), row = Math.floor(r() * 3);
  const names = ["Exceeds", "Meets", "Below"], g = [[7, 5, 3], [4, 3, 2], [2, 0, 0]], pct = g[row][col], raise = sal * pct / 100;
  const others = [7, 5, 4, 3, 2, 0].filter(x => x !== pct).map(x => fmt$(sal * x / 100));
  return { q: `Using the merit grid: an employee rated ${names[row].toUpperCase()} earns ${fmt$(sal)} in a range with a ${fmt$(mid)} midpoint. How much is the raise in dollars?`, tbl: T_GRID10,
    a: opts4(fmt$(raise), shuffle(others, r)), e: `Compa-ratio = ${fmt$(sal)} ÷ ${fmt$(mid)} = ${cr}% → ${names[row]} → ${pct}% × ${fmt$(sal)} = ${fmt$(raise)}.` }; });
G(10, 2, r => { const rate = rp(r, [0.4, 0.5, 0.75, 1.25]), u = rp(r, [800, 1000, 1200, 1500]), pay = rate * u;
  return { q: `A straight piece-rate plan pays $${rate.toFixed(2)} per unit. A worker produces ${u.toLocaleString("en-US")} units this week. What is the pay?`,
    a: opts4(fmt$(pay), [fmt$(pay * 1.1), fmt$(pay / 2), fmt$(rate * (u - 100))], fbM(pay)), e: `$${rate.toFixed(2)} × ${u} = ${fmt$(pay)}.` }; });
G(10, 3, r => { const std = rp(r, [1.5, 2, 2.5]), rate = rp(r, [20, 24, 30]), jobs = rp(r, [6, 7, 8]), pay = jobs * std * rate;
  return { q: `A standard-hour plan allows ${std} hours per job at $${rate}/hour. A mechanic completes ${jobs} jobs in an 8-hour day. What is the pay for the day?`,
    a: opts4(fmt$(pay), [fmt$(8 * rate), fmt$(jobs * rate), fmt$(pay + 8 * rate)], fbM(pay)),
    e: `Paid on standard time: ${jobs} jobs × ${std} hrs = ${jobs * std} hrs × $${rate} = ${fmt$(pay)} (vs. ${fmt$(8 * rate)} for 8 actual hours).` }; });
G(10, 2, r => { const sv = rp(r, [120000, 200000, 240000, 300000]), sh = rp(r, [40, 50, 60]), n = rp(r, [50, 80, 100, 120]), per = sv * sh / 100 / n;
  return { q: `A gainsharing plan shares ${sh}% of measured cost savings equally among ${n} employees. The plant saves ${fmt$(sv)} versus its baseline. What does each employee receive?`,
    a: opts4(fmt$(per), [fmt$(sv / n), fmt$(sv * sh / 100), fmt$(per * 2)], fbM(per)), e: `${fmt$(sv)} × ${sh}% = ${fmt$(sv * sh / 100)} pool ÷ ${n} = ${fmt$(per)}.` }; });
G(10, 3, r => { const s = rp(r, [50000, 60000, 75000]), p = rp(r, [3, 4, 5]), x = s * p / 100;
  return { q: `An employee earning ${fmt$(s)} gets a ${p}% reward this year and no other raises for 3 years. Compare the 3-year cost of a ${p}% MERIT INCREASE with a one-time ${p}% LUMP-SUM bonus.`,
    a: [`Merit: ${fmt$(3 * x)}; lump sum: ${fmt$(x)}`, `Merit: ${fmt$(x)}; lump sum: ${fmt$(3 * x)}`, `Both cost ${fmt$(x)}`, `Both cost ${fmt$(3 * x)}`],
    e: `A merit increase builds into base, so the ${fmt$(x)} repeats every year (${fmt$(3 * x)} over 3 years). A lump sum is paid once (${fmt$(x)}).` }; });
G(11, 3, r => { const col = Math.floor(r() * 3), cr = rp(r, [[0.84, 0.86, 0.88], [0.95, 1.0, 1.05], [1.12, 1.15, 1.18]][col]), mid = rp(r, [50000, 60000, 64000, 70000]), sal = Math.round(mid * cr), row = Math.floor(r() * 2);
  const names = ["Exceeds", "Meets"], g = [[6, 5, 4], [4, 3, 2]], pct = g[row][col], ns = sal * (1 + pct / 100);
  const others = [6, 5, 4, 3, 2].filter(x => x !== pct).map(x => fmt$(sal * (1 + x / 100)));
  return { q: `Using the merit grid: salary ${fmt$(sal)}, range midpoint ${fmt$(mid)}, rated ${names[row].toUpperCase()}. What is the new salary?`, tbl: T_GRID11,
    a: opts4(fmt$(ns), shuffle(others, r)), e: `Compa-ratio = ${cr.toFixed(2)} → ${pct}% → ${fmt$(sal)} × ${(1 + pct / 100).toFixed(2)} = ${fmt$(ns)}.` }; });
function genFor(chs, r, tag) { return GENS.filter(g => chs.includes(g.c)).map((g, k) => ({ ...g.make(r), id: tag + "-" + k, kind: "mc", c: g.c, d: g.d })); }

