      { p: 2, l: "Risk of leading: cost needs a return", re: [/cost/, /expens/, /return/, /productiv/] },
      { p: 2, l: "Risk of lagging: attraction/retention", re: [/retain|retention/, /turnover/, /attract/, /hir/, /recruit/, /quit|leave/] }
